# Generated by AI

import json
from functools import lru_cache

from pydantic import TypeAdapter

from app.core.language import Language
from app.schemas.crop import Crop
from app.utils.geo import DATA_DIR


@lru_cache(maxsize=1)
def get_crops() -> list[Crop]:
    return TypeAdapter(list[Crop]).validate_json((DATA_DIR / "crops.json").read_bytes())


@lru_cache(maxsize=1)
def english_crops() -> list[Crop]:
    entries = json.loads((DATA_DIR / "crops.en.json").read_text(encoding="utf-8"))
    crops = []
    for crop in get_crops():
        translation = {**entries[crop.id]}
        titles = translation.pop("reference_titles")
        references = [
            reference.model_copy(update={"title": title})
            for reference, title in zip(crop.references, titles, strict=True)
        ]
        crops.append(Crop.model_validate({
            **crop.model_dump(), **translation, "references": references,
        }))
    return crops


def get_display_crops(language: Language) -> list[Crop]:
    return english_crops() if language == "en" else get_crops()
